from pathlib import Path
import sys,hashlib
p=Path(__file__).parent;r=Path('/home/reinsirk/Atcoder_Env');s=Path(sys.argv[1]).read_text();s=s.replace('符号なしバイト列をO(|s|)時間・空間で構築','符号なしバイト列をO(|s|+1)時間・空間で構築')
needle='// コピーは独立し代入は強い例外保証。ムーブ元は空（自身へのムーブ代入は保持）。swapはO(1)。';assert s.count(needle)==1
s=s.replace(needle,'// assign(s): 現在の底で再構築、O(旧長+|s|+1)上界、強い例外保証。clear(): 空へ戻して底・容量を保持、O(旧長+1)上界、noexcept。
// 元文字列は保持しない。コピーはO(n+1)で独立、代入は強い例外保証。ムーブ元は空（自己ムーブ代入は保持）。swapはO(1)。')
needle='    RollingHash(const RollingHash& other)';assert s.count(needle)==1
s=s.replace(needle,'    void assign(std::string_view s) {
        RollingHash replacement(s, base_);
        swap(replacement);
    }

    void clear() noexcept {
        data_.clear(); power_data_.clear();
        offset_ = 0; powers_ = nullptr;
    }

'+needle)
(p/'final.hpp').write_text(s);(r/'String/RollingHash.cpp').write_text(s);print('installed',hashlib.sha256(s.encode()).hexdigest())

