p=Path(__file__).parent;o=p/'official';o.mkdir(exist_ok=True);base='https://raw.githubusercontent.com/yosupo06/library-checker-problems/master/';prefix='string/zalgorithm/';ip=prefix+'info.toml';info=urllib.request.urlopen(base+ip,timeout=30).read();(o/'info.toml').write_bytes(info);d=tomllib.loads(info.decode())
files=['common/random.h','common/testlib.h',prefix+'task.md']
for t in d['tests']:
 if t['name'].endswith('.cpp'):files.append(prefix+'gen/'+t['name'])
 else:files.extend(prefix+'gen/'+Path(t['name']).stem+f'_{i:02}.in'for i in range(t['number']))
def get(n):
 data=urllib.request.urlopen(base+n,timeout=30).read();f=(p/'common'/Path(n).name)if n.startswith('common/')else(o/Path(n).name);f.parent.mkdir(exist_ok=True);f.write_bytes(data);return dict(source=n,url=base+n,sha256=hashlib.sha256(data).hexdigest(),bytes=len(data))
with concurrent.futures.ThreadPoolExecutor(max_workers=6)as pool:rows=list(pool.map(get,files))
rows.append(dict(source=ip,url=base+ip,sha256=hashlib.sha256(info).hexdigest(),bytes=len(info)));(p/'official_sources.json').write_text(json.dumps(rows,indent=2)+'\n');print('fetched',len(rows),'official files')

