#include <algorithm>
#include <cstddef>
#include <iostream>
#include <string>
#include <vector>
// ハッシュを使わず、確定済み区間を再利用する線形Z参照。
int main() {
    std::ios::sync_with_stdio(false); std::cin.tie(nullptr);
    std::string s; if (!(std::cin>>s)) return 0;
    const std::size_t n=s.size(); std::vector<std::size_t> z(n);
    if(n) z[0]=n;
    std::size_t l=0,r=0;
    for(std::size_t i=1;i<n;++i) {
        if(i<r) z[i]=std::min(r-i,z[i-l]);
        while(i+z[i]<n && s[z[i]]==s[i+z[i]]) ++z[i];
        if(i+z[i]>r) { l=i; r=i+z[i]; }
    }
    for(std::size_t i=0;i<n;++i) { if(i) std::cout<<' '; std::cout<<z[i]; }
    std::cout<<'\n';
}

