from pathlib import Path
import subprocess,json,hashlib
p=Path(__file__).parent;r=Path('/home/reinsirk/Atcoder_Env');o=p/'official_final';o.mkdir(exist_ok=True);sha=lambda b:hashlib.sha256(b).hexdigest();source=(r/'String/RollingHash.cpp').read_bytes();assert source==(p/'final.hpp').read_bytes();builds=[];records=[];local=[]
cases=[(p/'official'/x['name'],'official')for x in json.loads((p/'official_cases.json').read_text())]+[(p/'custom'/x['name'],'custom')for x in json.loads((p/'custom_cases.json').read_text())]
for mode,cc in {'gcc':['g++'],'clang':['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0']}.items():
 for skip in [False,True]:
  for standard in [False,True]:
   name=mode+('_skip'if skip else'_checked')+('_standard'if standard else'_native');flags=['-DSIRKIT_FORCE_STANDARD_ARITHMETIC','-U__SIZEOF_INT128__','-DSIRKIT_DISABLE_SIMD']if standard else[]
   for entry in ['rolling_hash','rolling_hash_local']:
    submission=(r/'Verify/current/submissions'/(entry+'.cpp')).read_bytes();data=submission if skip else submission.replace(b'#define SKIP_RUNTIME_CHECKS\n',b'',1)
    if skip and entry=='rolling_hash_local':data=b'#define SKIP_RUNTIME_CHECKS\n'+data
    cpp=o/(name+'_'+entry+'.cpp');cpp.write_bytes(data);exe=cpp.with_suffix('');cmd=['taskset','-c','6',*cc,'-std=c++23','-O2','-Wall','-Wextra','-Werror','-pedantic-errors',*flags,str(cpp),'-o',str(exe)];built=subprocess.run(cmd,capture_output=True,text=True);assert built.returncode==0,built.stderr;assert not built.stderr;builds.append(dict(name=name,entry=entry,command=cmd,sha256=sha(data),build_returncode=built.returncode,stderr=built.stderr))
    if entry=='rolling_hash_local':
     run=subprocess.run([str(exe)],capture_output=True);assert run.returncode==0 and not run.stderr and run.stdout==b'OK\n';local.append(dict(build=name,stdout=run.stdout.decode(),returncode=run.returncode));continue
    for f,scope in cases:
     data=f.read_bytes();ref=(p/'reference_outputs'/(f.name+'.out')).read_bytes();run=subprocess.run([str(exe)],input=data,capture_output=True);assert run.returncode==0 and not run.stderr,(name,f.name,run.stderr);assert run.stdout.split()==ref.split(),(name,f.name);records.append(dict(build=name,case=f.name,scope=scope,input_sha256=sha(data),output_sha256=sha(run.stdout),reference_output_sha256=sha(ref),answers=len(ref.split()),returncode=run.returncode,stderr_bytes=len(run.stderr)))
   print(name,'PASS',len(cases),'+local',flush=True)
assert (r/'String/RollingHash.cpp').read_bytes()==source
result=dict(status='PASS',source_sha256=sha(source),submission_sha256=sha((r/'Verify/current/submissions/rolling_hash.cpp').read_bytes()),official_runs=sum(x['scope']=='official'for x in records),custom_runs=sum(x['scope']=='custom'for x in records),local_runs=local,builds=builds,records=records,note='全Z値を、文字だけを比較する線形Zアルゴリズムの独立参照と整数列で完全一致確認。native128/標準32ビット分割算術の両経路。有限入力で衝突が観測されなかった結果であり、衝突が無い保証ではない。')
(o/'results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print('official/custom PASS',len(records),'local',len(local))
